  get filepath_raw(): H.Ref<string>;
  set filepath_raw(v: H.In<string>);
  /** Format used for re-saving this file Default: 'TARGA'. */
  get file_format(): H.Ref<E.ImageFileFormat>;
  set file_format(v: H.In<E.ImageFileFormat>);
  /**
   * Where the image comes from Default: 'FILE'.
   * - `FILE`: Single Image (Single image file)
   * - `SEQUENCE`: Image Sequence (Multiple image files, as a sequence)
   * - `MOVIE`: Movie (Movie file)
   * - `GENERATED`: Generated (Generated image)
   * - `VIEWER`: Viewer (Compositing node viewer)
   * - `TILED`: UDIM Tiles (Tiled UDIM image texture)
   */
  get source(): H.Ref<"FILE" | "SEQUENCE" | "MOVIE" | "GENERATED" | "VIEWER" | "TILED" | (string & {})>;
  set source(v: H.In<"FILE" | "SEQUENCE" | "MOVIE" | "GENERATED" | "VIEWER" | "TILED" | (string & {})>);
  /**
   * How to generate the image Default: 'IMAGE'.
   * - `IMAGE`: Image
   * - `MULTILAYER`: Multilayer
   * - `UV_TEST`: UV Test
   * - `RENDER_RESULT`: Render Result
   * - `COMPOSITING`: Compositing
   */
  get type(): H.Ref<"IMAGE" | "MULTILAYER" | "UV_TEST" | "RENDER_RESULT" | "COMPOSITING">;
  /** First packed file of the image */
  get packed_file(): H.Ptr<R.PackedFile>;
  /** Collection of packed images */
  readonly packed_files: H.Own<H.Coll<R.ImagePackedFile>>;
  /** Apply render part of display transformation when displaying this image on the screen Default: False. */
  get use_view_as_render(): H.Ref<boolean>;
  set use_view_as_render(v: H.In<boolean>);
  /** Deinterlace movie file on load Default: False. */
  get use_deinterlace(): H.Ref<boolean>;
  set use_deinterlace(v: H.In<boolean>);
  /** Use Multiple Views (when available) Default: False. */
  get use_multiview(): H.Ref<boolean>;
  set use_multiview(v: H.In<boolean>);
  /** Image has left and right views Default: False. */
  get is_stereo_3d(): H.Ref<boolean>;
  /** Image has more than one view Default: False. */
  get is_multiview(): H.Ref<boolean>;
  /** Image has changed and is not saved Default: False. */
  get is_dirty(): H.Ref<boolean>;
  /**
   * Generated image type Default: 'UV_GRID'.
   * - `BLANK`: Blank (Generate a blank image)
   * - `UV_GRID`: UV Grid (Generated grid to test UV mappings)
   * - `COLOR_GRID`: Color Grid (Generated improved UV grid to test UV mappings)
   */
  get generated_type(): H.Ref<"BLANK" | "UV_GRID" | "COLOR_GRID">;
  set generated_type(v: H.In<"BLANK" | "UV_GRID" | "COLOR_GRID">);
  /** Generated image width Range: 1 to 65536. Default: 1024. */
  get generated_width(): H.Ref<number>;
  set generated_width(v: H.In<number>);
  /** Generated image height Range: 1 to 65536. Default: 1024. */
  get generated_height(): H.Ref<number>;
  set generated_height(v: H.In<number>);
  /** Generate floating-point buffer Default: False. */
  get use_generated_float(): H.Ref<boolean>;
  set use_generated_float(v: H.In<boolean>);
  /** Fill color for the generated image Range: 0 to inf. Default: (0.0, 0.0, 0.0, 0.0). */
  get generated_color(): H.Arr<number>;
  set generated_color(v: H.In<readonly number[]>);
  /** Display Aspect for this image, does not affect rendering Range: 0.10000000149011612 to inf. Default: (1.0, 1.0). */
  get display_aspect(): H.Remote<M.Vector>;
  set display_aspect(v: H.In<M.VectorLike>);
  /** Render slots of the image */
  readonly render_slots: H.Own<H.Coll<R.RenderSlot> & R.RenderSlots>;
  /** Tiles of the image */
  readonly tiles: H.Own<H.Coll<R.UDIMTile> & R.UDIMTiles>;
  /** True if the image data is loaded into memory Default: False. */
  get has_data(): H.Ref<boolean>;
  /** Image bit depth Range: 0 to 2147483647. Default: 0. */
