  /** Width and height of the image buffer in pixels, zero when image data cannot be loaded Range: -2147483648 to 2147483647. Default: (0, 0). */
  get size(): H.Arr<number>;
  /** X/Y pixels per meter, for the image buffer Default: (0.0, 0.0). */
  get resolution(): H.Remote<M.Vector>;
  set resolution(v: H.In<M.VectorLike>);
  /** Duration (in frames) of the image (1 when not a video/sequence) Range: 0 to 2147483647. Default: 0. */
  get frame_duration(): H.Ref<number>;
  /** Image buffer pixels in floating-point values Default: 0.0. */
  get pixels(): H.Arr<number>;
  set pixels(v: H.In<readonly number[]>);
  /** Number of channels in pixels buffer Range: 0 to 2147483647. Default: 0. */
